 async function aggregates(siteId:string,b:{start:string;end:string}){
  const stats=await querySemanticStats(ctx,siteId,b.start,b.end);
  // Explicit allowlist: no visitor identifiers, profiles or raw event payloads reach models.
  const days=Math.round((new Date(b.end).getTime()-new Date(b.start).getTime())/86400000)+1;if(days<1||days>31)throw new ExternalError('aggregate_range_invalid');const priorEnd=new Date(new Date(b.start).getTime()-86400000).toISOString().slice(0,10),priorStart=new Date(new Date(b.start).getTime()-days*86400000).toISOString().slice(0,10);const previous=await querySemanticStats(ctx,siteId,priorStart,priorEnd);
  const deltas:{dimension:string;value:string;current:number;previous:number;delta:number;relative:number|null}[]=[];for(const [dimension,currentRows,priorRows] of [['source',stats.sources.map(r=>[r.channel,r.pv]),previous.sources.map(r=>[r.channel,r.pv])],['page',stats.pages.map(r=>[r.path,r.pv]),previous.pages.map(r=>[r.path,r.pv])],['device',Object.entries(stats.audience.device??{}),Object.entries(previous.audience.device??{})]] as [string,[string,number][],[string,number][]][]){const current=new Map(currentRows),prior=new Map(priorRows);for(const value of new Set([...current.keys(),...prior.keys()])){const now=current.get(value)??0,before=prior.get(value)??0;deltas.push({dimension,value,current:now,previous:before,delta:now-before,relative:before?(now-before)/before:null});}}deltas.sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));
  const seo=(await pool.query('SELECT id,created_at,results FROM seo_scans WHERE site_id=$1 ORDER BY created_at DESC LIMIT 1',[siteId])).rows[0];
  const definitions=(await pool.query('SELECT id,name,steps FROM funnels WHERE site_id=$1 ORDER BY id LIMIT 20',[siteId])).rows;const funnels=definitions.map(f=>({id:f.id,name:f.name,steps:stats.funnels[f.id]??[],stepLabels:(f.steps as {value:string}[]).map(step=>step.value),status:stats.funnelStatus}));
  const safe=stats as unknown as Record<string,unknown>;return {aggregation:stats.aggregation,timezone:safe.timezone,precision:safe.precision,sliceLimit:10,funnels,comparison:{period:{start:priorStart,end:priorEnd},totals:previous.totals,largestChanges:deltas.slice(0,10),caveat:'边际维度变化只定位观察性候选原因，不能证明因果'},seo:seo?{scanId:seo.id,createdAt:seo.created_at,pages:seo.results.slice(0,10)}:null,totals:safe.totals,pages:Array.isArray(safe.pages)?safe.pages.slice(0,10):[],sources:Array.isArray(safe.sources)?safe.sources.slice(0,10):[],audience:Object.fromEntries(Object.entries((safe.audience??{}) as Record<string,Record<string,number>>).map(([k,v])=>[k,Object.fromEntries(Object.entries(v).slice(0,10))])),events:Array.isArray(safe.events)?safe.events.slice(0,10).map((e:Record<string,unknown>)=>({name:e.name,count:e.count,uv:e.uv})):[],vitals:Array.isArray(safe.vitals)?safe.vitals.slice(0,10):[],trend:Array.isArray(safe.trend)?safe.trend.slice(0,24):[],period:b};
 }
