 async function alertWindow(siteId:string,observed:string,metric:'pv'|'uv'='pv'){
  const hour=new Date(observed);if(!Number.isFinite(hour.getTime())||hour.getTime()%3600000!==0)throw new ExternalError('aggregate_range_invalid');
  const client=await pool.connect();try{await client.query('BEGIN');await lockSite(client,siteId);
  const state=(await client.query('SELECT generation,processed_generation FROM aggregation_state WHERE site_id=$1',[siteId])).rows[0];if(!state||String(state.generation)!==String(state.processed_generation))throw new ExternalError('aggregation_pending');
  const rows=(await client.query("SELECT h.hour,s.data FROM generate_series($2::timestamptz-interval '28 days',$2::timestamptz,interval '1 day') h(hour) LEFT JOIN stats_hourly s ON s.site_id=$1 AND s.hour=h.hour ORDER BY h.hour DESC",[siteId,observed])).rows as {hour:Date;data:import('./analytics.js').Bucket|null}[];
  const current=new Map<string,number>(),baseline=new Map<string,number>();let total=0,prior=0,currentUV=0,priorUV=0;
  for(const [i,row]of rows.entries()){const data=row.data;if(!data)continue;if(i===0){total=data.pv;}else{prior+=data.pv;}const jointCounts=new Map<string,{pv:number;visitors:Set<string>}>();for(const [encoded,segment]of Object.entries(data.segments??{})){const dimensions=JSON.parse(encoded) as Record<string,string>;const joint=JSON.stringify({channel:dimensions.channel??'unknown',page:dimensions.path??'unknown',device:dimensions.device??'unknown'});const counts=jointCounts.get(joint)??{pv:0,visitors:new Set<string>()};counts.pv+=segment.pv;for(const visitor of segment.visitors)counts.visitors.add(visitor);jointCounts.set(joint,counts);}for(const [joint,counts]of jointCounts){const map=i===0?current:baseline;map.set(joint,(map.get(joint)??0)+counts.pv);}}
  const source=publishedMemberSource(siteId,new Date(hour.getTime()-28*86400000).toISOString(),new Date(hour.getTime()+3600000).toISOString());
  const uvRows=(await client.query(`SELECT date_trunc('hour',event_ts AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour,CASE WHEN metric='visitors' THEN NULL ELSE jsonb_build_object('channel',COALESCE((key->>0)::jsonb->>'channel','unknown'),'page',COALESCE((key->>0)::jsonb->>'path','unknown'),'device',COALESCE((key->>0)::jsonb->>'device','unknown'))::text END AS joint,count(DISTINCT visitor_id)::int AS n FROM (${source.sql}) facts WHERE metric IN('visitors','segmentVisitor') AND mod(extract(epoch FROM((date_trunc('hour',event_ts AT TIME ZONE 'UTC') AT TIME ZONE 'UTC')-$2::timestamptz)),86400)=0 GROUP BY 1,2`,source.values)).rows;
  if(metric==='uv'){current.clear();baseline.clear();}
  for(const row of uvRows){const isCurrent=+new Date(row.hour)===+hour;if(row.joint===null){if(isCurrent)currentUV=Number(row.n);else priorUV+=Number(row.n);}else if(metric==='uv'){const map=isCurrent?current:baseline,key=JSON.stringify(JSON.parse(row.joint));map.set(key,(map.get(key)??0)+Number(row.n));}}
  const changes=[...new Set([...current.keys(),...baseline.keys()])].map(key=>{const now=current.get(key)??0,mean=(baseline.get(key)??0)/28;return {dimensions:JSON.parse(key) as Record<string,string>,current:now,baselineMean:mean,delta:now-mean,relative:mean?(now-mean)/mean:null};}).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)).slice(0,10);
  const result={precision:'complete-hour',observedHour:observed,end:new Date(hour.getTime()+3600000).toISOString(),baseline:'此前28天相同UTC小时，缺失小时按零计入；站点时区跨DST可能改变本地时刻',baselineDays:28,metric,currentPV:total,baselineMeanPV:prior/28,currentUV,baselineMeanUV:priorUV/28,largestJointChanges:changes,source:'stats_hourly-and-exact-published-members',caveat:'渠道×页面×设备变化是观察性候选，不构成因果证明；迟到数据重算可能改变聚合版本，原始告警快照保留以便比较'};await client.query('COMMIT');return result;}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}
 }
